CREATE FUNCTION public.match_migration_changed() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE item jsonb;r public.player_match_observations; v_entity bigint;
BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'History migration in progress; TRUNCATE is disabled'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(CASE TG_OP WHEN 'INSERT' THEN jsonb_build_array(to_jsonb(NEW)) WHEN 'DELETE' THEN jsonb_build_array(to_jsonb(OLD)) ELSE jsonb_build_array(to_jsonb(OLD),to_jsonb(NEW)) END) LOOP
 r:=jsonb_populate_record(NULL::public.player_match_observations,item);
 -- Deletes never recreate an entity removed by a parent FK cascade.
 SELECT entity_id INTO v_entity FROM public.match_history_entities e WHERE e.player_id IS NOT DISTINCT FROM r.player_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season AND e.scoring_version IS NOT DISTINCT FROM r.scoring_version AND e.round IS NOT DISTINCT FROM r.round AND e.source_round_key IS NOT DISTINCT FROM r.source_round_key;
 IF v_entity IS NULL AND TG_OP<>'DELETE' THEN
 INSERT INTO public.match_history_entities(player_id,championship_id,competition_id,season,scoring_version,round,source_round_key) VALUES(r.player_id,r.championship_id,r.competition_id,r.season,r.scoring_version,r.round,r.source_round_key) ON CONFLICT DO NOTHING;
 SELECT entity_id INTO v_entity FROM public.match_history_entities e WHERE e.player_id IS NOT DISTINCT FROM r.player_id AND e.championship_id IS NOT DISTINCT FROM r.championship_id AND e.competition_id IS NOT DISTINCT FROM r.competition_id AND e.season IS NOT DISTINCT FROM r.season AND e.scoring_version IS NOT DISTINCT FROM r.scoring_version AND e.round IS NOT DISTINCT FROM r.round AND e.source_round_key IS NOT DISTINCT FROM r.source_round_key;
 END IF;
 IF v_entity IS NOT NULL THEN
 INSERT INTO public.match_migration_queue VALUES(v_entity) ON CONFLICT(entity_id) DO UPDATE SET entity_id=excluded.entity_id;
 DELETE FROM public.match_migration_verified WHERE entity_id=v_entity;
 END IF;
 END LOOP;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.match_migration_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER history_migration_changed AFTER INSERT OR UPDATE OR DELETE ON public.player_match_observations FOR EACH ROW EXECUTE FUNCTION public.match_migration_changed();
CREATE TRIGGER history_migration_no_truncate BEFORE TRUNCATE ON public.player_match_observations FOR EACH STATEMENT EXECUTE FUNCTION public.match_migration_changed();
CREATE FUNCTION public.match_migration_seed(p_limit integer DEFAULT 10000) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE n bigint;cursor_value jsonb;predicate text:='true';
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>20000 THEN RAISE EXCEPTION 'Invalid discovery page size'; END IF;
 PERFORM 1 FROM public.match_migration_status WHERE id FOR UPDATE;
 IF (SELECT seeded FROM public.match_migration_status WHERE id) THEN RETURN 0; END IF;
 SELECT seed_cursor INTO cursor_value FROM public.match_migration_status WHERE id;
 IF cursor_value IS NOT NULL THEN
 SELECT '(player_id,championship_id,competition_id,season,scoring_version,round,source_round_key,observed_at) > ('||string_agg(quote_literal(cursor_value->>k),',' ORDER BY ord)||')' INTO predicate FROM unnest(ARRAY['player_id','championship_id','competition_id','season','scoring_version','round','source_round_key','observed_at']) WITH ORDINALITY AS cols(k,ord);
 END IF;
 CREATE TEMP TABLE IF NOT EXISTS match_seed_page ON COMMIT DROP AS SELECT player_id,championship_id,competition_id,season,scoring_version,round,source_round_key,observed_at FROM public.player_match_observations WITH NO DATA;
 TRUNCATE pg_temp.match_seed_page;
 EXECUTE 'INSERT INTO pg_temp.match_seed_page SELECT player_id,championship_id,competition_id,season,scoring_version,round,source_round_key,observed_at FROM public.player_match_observations WHERE '||predicate||' ORDER BY player_id,championship_id,competition_id,season,scoring_version,round,source_round_key,observed_at LIMIT '||p_limit;
 GET DIAGNOSTICS n=ROW_COUNT;
 INSERT INTO public.match_history_entities(player_id,championship_id,competition_id,season,scoring_version,round,source_round_key) SELECT DISTINCT player_id,championship_id,competition_id,season,scoring_version,round,source_round_key FROM pg_temp.match_seed_page ON CONFLICT DO NOTHING;
 INSERT INTO public.match_migration_queue SELECT e.entity_id FROM (SELECT DISTINCT player_id,championship_id,competition_id,season,scoring_version,round,source_round_key FROM pg_temp.match_seed_page) o JOIN public.match_history_entities e ON e.player_id = o.player_id AND e.championship_id = o.championship_id AND e.competition_id = o.competition_id AND e.season = o.season AND e.scoring_version = o.scoring_version AND e.round = o.round AND e.source_round_key = o.source_round_key ON CONFLICT DO NOTHING;
 IF n>0 THEN SELECT to_jsonb(o) INTO cursor_value FROM pg_temp.match_seed_page o ORDER BY player_id DESC,championship_id DESC,competition_id DESC,season DESC,scoring_version DESC,round DESC,source_round_key DESC,observed_at DESC LIMIT 1; END IF;
 UPDATE public.match_migration_status SET seed_cursor=cursor_value,seeded=n<p_limit WHERE id;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.match_migration_seed(integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.match_migration_batch(p_limit integer DEFAULT 25,p_budget_ms integer DEFAULT 5000) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE job record;identity jsonb;predicate text;started timestamptz:=clock_timestamp();n integer:=0;src bigint;dst bigint;mismatch boolean;
BEGIN
 IF p_limit<1 OR p_limit>200 OR p_limit IS NULL OR p_budget_ms<1 OR p_budget_ms>20000 OR p_budget_ms IS NULL THEN RAISE EXCEPTION 'Invalid batch bounds'; END IF;
 IF NOT (SELECT seeded AND completed_at IS NULL FROM public.match_migration_status WHERE id) THEN RAISE EXCEPTION 'Migration is not ready for batches'; END IF;
 -- Match cutover lock order and prevent cutover while a batch is active.
 LOCK TABLE public.player_match_observations IN ACCESS SHARE MODE;
 CREATE TEMP TABLE IF NOT EXISTS match_batch_source ON COMMIT DROP AS SELECT * FROM public.player_match_observations WITH NO DATA;
 CREATE TEMP TABLE IF NOT EXISTS match_batch_retained ON COMMIT DROP AS SELECT o.*,NULL::text AS _migration_signature FROM public.player_match_observations o WITH NO DATA;
 FOR job IN SELECT entity_id FROM public.match_migration_queue ORDER BY entity_id LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
 SELECT to_jsonb(e) INTO identity FROM public.match_history_entities e WHERE entity_id=job.entity_id;
 IF identity IS NULL THEN CONTINUE; END IF;
 SELECT string_agg(format('%I',k)||CASE WHEN identity->>k IS NULL THEN ' IS NULL' ELSE '='||quote_literal(identity->>k) END,' AND ') INTO predicate FROM unnest(ARRAY['player_id','championship_id','competition_id','season','scoring_version','round','source_round_key']) k;
 TRUNCATE pg_temp.match_batch_source,pg_temp.match_batch_retained;
 EXECUTE 'INSERT INTO pg_temp.match_batch_source SELECT * FROM public.player_match_observations WHERE '||predicate;
 GET DIAGNOSTICS src=ROW_COUNT;
 INSERT INTO pg_temp.match_batch_retained SELECT (original).*,NULL::text FROM (
 SELECT o AS original,(observed_at IS NULL OR NOT isfinite(observed_at)) AS uncertain,ROW(points,score_status,is_home,minutes_raw,start_raw,participation,round_id,match_id,source_round_number,occurred_at,round_start_at) AS fact,
 lag(ROW(points,score_status,is_home,minutes_raw,start_raw,participation,round_id,match_id,source_round_number,occurred_at,round_start_at)) OVER w AS preceding,lead(ROW(points,score_status,is_home,minutes_raw,start_raw,participation,round_id,match_id,source_round_number,occurred_at,round_start_at)) OVER w AS following
 FROM pg_temp.match_batch_source o WINDOW w AS (ORDER BY observed_at)
 ) periods WHERE uncertain OR fact IS DISTINCT FROM preceding OR fact IS DISTINCT FROM following;
 GET DIAGNOSTICS dst=ROW_COUNT;
 UPDATE pg_temp.match_batch_retained o SET _migration_signature=md5(jsonb_build_array(o.points,o.score_status,o.is_home,o.minutes_raw,o.start_raw,o.participation,o.round_id,o.match_id,o.source_round_number,o.occurred_at,o.round_start_at)::text);
 ANALYZE pg_temp.match_batch_retained(_migration_signature);
 DELETE FROM public.match_history_times WHERE entity_id=job.entity_id;
 DELETE FROM public.match_history_states WHERE entity_id=job.entity_id;
 INSERT INTO public.match_history_states(entity_id,signature,points,score_status,is_home,minutes_raw,start_raw,participation,round_id,match_id,source_round_number,occurred_at,round_start_at) SELECT DISTINCT job.entity_id,o._migration_signature,o.points,o.score_status,o.is_home,o.minutes_raw,o.start_raw,o.participation,o.round_id,o.match_id,o.source_round_number,o.occurred_at,o.round_start_at FROM pg_temp.match_batch_retained o;
 INSERT INTO public.match_history_times(entity_id,state_id,observed_at) SELECT job.entity_id,s.state_id,o.observed_at FROM pg_temp.match_batch_retained o JOIN public.match_history_states s ON s.entity_id=job.entity_id AND s.signature=o._migration_signature AND s.points IS NOT DISTINCT FROM o.points AND s.score_status IS NOT DISTINCT FROM o.score_status AND s.is_home IS NOT DISTINCT FROM o.is_home AND s.minutes_raw IS NOT DISTINCT FROM o.minutes_raw AND s.start_raw IS NOT DISTINCT FROM o.start_raw AND s.participation IS NOT DISTINCT FROM o.participation AND s.round_id IS NOT DISTINCT FROM o.round_id AND s.match_id IS NOT DISTINCT FROM o.match_id AND s.source_round_number IS NOT DISTINCT FROM o.source_round_number AND s.occurred_at IS NOT DISTINCT FROM o.occurred_at AND s.round_start_at IS NOT DISTINCT FROM o.round_start_at;
 -- Full retained-row equality, including IDs, nulls, payloads and timestamp precision.
 EXECUTE 'SELECT EXISTS((SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.match_batch_retained o EXCEPT ALL SELECT to_jsonb(v) FROM public.match_history_preview v WHERE '||predicate||') UNION ALL (SELECT to_jsonb(v) FROM public.match_history_preview v WHERE '||predicate||' EXCEPT ALL SELECT to_jsonb(o)-''_migration_signature'' FROM pg_temp.match_batch_retained o))' INTO mismatch;
 IF mismatch THEN RAISE EXCEPTION 'Retained history verification failed'; END IF;
 INSERT INTO public.match_migration_verified VALUES(job.entity_id,src,dst,clock_timestamp()) ON CONFLICT(entity_id) DO UPDATE SET source_rows=excluded.source_rows,endpoint_rows=excluded.endpoint_rows,verified_at=excluded.verified_at;
 DELETE FROM public.match_migration_queue WHERE entity_id=job.entity_id;
 n:=n+1;
 EXIT WHEN extract(epoch FROM clock_timestamp()-started)*1000>=p_budget_ms;
 END LOOP;
 RETURN jsonb_build_object('processed',n,'pending',(SELECT count(*) FROM public.match_migration_queue),'verified',(SELECT count(*) FROM public.match_migration_verified));
END $$;
REVOKE ALL ON FUNCTION public.match_migration_batch(integer,integer) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
